using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using HarmonyLib;using Verse;
namespace Igor.WorksitesRussian{public static class WorksiteOfferPanicPatch{
private static bool Russian=>LanguageDatabase.activeLanguage?.folderName.StartsWith("Russian",StringComparison.OrdinalIgnoreCase)==true;
public static string Confirmation(string a,string b,string c)=>Russian?WorksiteOfferPanicText.Confirmation(a,b,c):string.Concat(a,b,c);
public static string DemandFour(string a,string b,string c,string d)=>Russian?WorksiteOfferPanicText.DemandFour(a,b,c,d):string.Concat(a,b,c,d);
public static string DemandArray(string[] a)=>Russian?WorksiteOfferPanicText.DemandArray(a):string.Concat(a);
public static string Fine(string a,object b,object c,object d)=>Russian?WorksiteOfferPanicText.Fine(a,b,c,d):string.Format(a,b,c,d);
public static string Stealth(string a,string b)=>Russian?WorksiteOfferPanicText.Stealth(a,b):string.Concat(a,b);
public static string Downed(string a,string b,string c,string d)=>Russian?WorksiteOfferPanicText.Downed(a,b,c,d):string.Concat(a,b,c,d);
public static string Witness(string a,string b,string c,string d)=>Russian?WorksiteOfferPanicText.Witness(a,b,c,d):string.Concat(a,b,c,d);
private static readonly Dictionary<string,Dictionary<string,Tuple<string,int>>> Bindings=new Dictionary<string,Dictionary<string,Tuple<string,int>>>{{"MiningOutpost.Parley.PlayerOffer:GetConfirmationText",new Dictionary<string,Tuple<string,int>>{{"Concat(System.String,System.String,System.String)",Tuple.Create("Confirmation",3)}}},{"MiningOutpost.Parley.AtonementGenerator:GenerateDemand",new Dictionary<string,Tuple<string,int>>{{"Concat(System.String,System.String,System.String,System.String)",Tuple.Create("DemandFour",1)},{"Concat(System.String[])",Tuple.Create("DemandArray",3)},{"Format(System.String,System.Object,System.Object,System.Object)",Tuple.Create("Fine",1)}}},{"MiningOutpost.WorkerPanicUtility:DisplayStealthKillMessage",new Dictionary<string,Tuple<string,int>>{{"Concat(System.String,System.String)",Tuple.Create("Stealth",1)}}},{"MiningOutpost.WorkerPanicUtility:DisplayDownedBeforeBackupMessage",new Dictionary<string,Tuple<string,int>>{{"Concat(System.String,System.String,System.String,System.String)",Tuple.Create("Downed",1)}}},{"MiningOutpost.WorkerPanicUtility:ShowWitnessAlertMessage",new Dictionary<string,Tuple<string,int>>{{"Concat(System.String,System.String,System.String,System.String)",Tuple.Create("Witness",1)}}}};
public static void Install(Harmony h){foreach(var key in Bindings.Keys)h.Patch(AccessTools.Method(key),transpiler:new HarmonyMethod(typeof(WorksiteOfferPanicPatch),nameof(Rewrite)));}
public static IEnumerable<CodeInstruction> Rewrite(IEnumerable<CodeInstruction> input,MethodBase __originalMethod){var specs=Bindings[__originalMethod.DeclaringType.FullName+":"+__originalMethod.Name];var seen=new Dictionary<string,int>();var output=new List<CodeInstruction>();foreach(var i in input){var c=new CodeInstruction(i);if(c.operand is MethodInfo m&&m.DeclaringType==typeof(string)){var sig=m.Name+"("+string.Join(",",m.GetParameters().Select(p=>p.ParameterType.FullName))+")";if(specs.TryGetValue(sig,out var spec)){c.operand=AccessTools.Method(typeof(WorksiteOfferPanicPatch),spec.Item1);seen[sig]=seen.TryGetValue(sig,out int n)?n+1:1;}}output.Add(c);}if(specs.Any(s=>!seen.TryGetValue(s.Key,out int n)||n!=s.Value.Item2))throw new InvalidOperationException("Offer/panic formatter contract changed: "+__originalMethod);return output;}
}}
